  `employee_id` int NOT NULL,
  `date` date NOT NULL,
  `check_in` time DEFAULT NULL,
  `check_out` time DEFAULT NULL,
  `work_hours` decimal(4,1) DEFAULT NULL,
  `status` enum('PRESENT','ABSENT','LATE','HALF_DAY','ON_LEAVE') COLLATE utf8mb4_unicode_ci NOT NULL,
  `note` text COLLATE utf8mb4_unicode_ci,
  `check_in_lat` decimal(9,6) DEFAULT NULL,
  `check_in_lng` decimal(9,6) DEFAULT NULL,
  `check_out_lat` decimal(9,6) DEFAULT NULL,
  `check_out_lng` decimal(9,6) DEFAULT NULL,
  `check_in_distance_m` int DEFAULT NULL,
  `is_within_geofence` tinyint(1) DEFAULT NULL,
  `source` enum('SELF','MANUAL') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tenant_id` int NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `employee_id` (`employee_id`,`date`),
  KEY `ix_attendance_tenant_id` (`tenant_id`),
  CONSTRAINT `attendance_ibfk_1` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`) ON DELETE CASCADE,
  CONSTRAINT `attendance_ibfk_2` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=161 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
